from common import *

def make(v):
    p=Paper(2016,v,'C');k=v+2
    p.mc('Reciprocal',f'{k}/{k+1} тооны урвууг ол.',F(k+1,k),'a/b-ийн урвуу b/a.',[F(-k,k+1),F(-(k+1),k),F(k,k+1),0])
    p.mc('Prime factors','Аль үржвэр зөвхөн анхны тоон үржигдэхүүнтэй вэ?',f'2·5·{[11,13,17,19,23][v-1]}','2,5 ба өгсөн гурав дахь тоо анхны; бусад сонголт нийлмэл үржигдэхүүнтэй.', ['3·5·9','2·7·15','3·7·27','2·5·21'])
    p.mc('Fraction comparison','Аль тэнцэтгэл биш худал вэ?',f'{k}/{k+2} > {k}/{k+1}','Ижил эерэг хүртвэртэй үед хуваарь их бол бутархай бага.',[f'{k+1}/{k} > 1',f'{k}/{k+1} < 1',f'{k+1}/{k+3} > {k+1}/{k+4}',f'{k}/{k+2} < {k+1}/{k+2}'])
    p.mc('Square properties','Квадратын талаар аль өгүүлбэр худал вэ?','Дотоод өнцгүүдийн нийлбэр 180°','Дөрвөн өнцөгтийн дотоод өнцгийн нийлбэр 360°.', ['Диагоналиудын урт тэнцүү','Диагоналиуд перпендикуляр','Эсрэг талууд параллель','Диагональ нь оройн өнцгийг хуваана'])
    p.mc('Single draw probability',f'Хайрцагт {k+2} цэнхэр, {k} шар, {k+3} улаан карт бий. Нэгийг сугалахад цэнхэр байх магадлалыг ол.',F(k+2,3*k+5),'Таатай картын тоог нийт картын тоонд хуваана.')
    p.mc('Linear equation',f'−2x/{k+2}=1 тэгшитгэлийг бод.',F(-k-2,2),'Хоёр талыг −(k+2)/2-оор үржүүл.')
    p.mc('Polynomial derivative',f'y=x⁴−{k}x²+6 функцийн уламжлалыг ол.',f'4x³−{2*k}x','Зэргийн дүрэм хэрэглэ.',[f'4x³−{k}x',f'x³−{2*k}x',f'4x⁴−{2*k}x',f'4x³+{2*k}x'])
    p.mc('Rational exponents',f'8^(2/3)+⁵√{(k+1)**5} утгыг ол.',k+5,'8^(1/3)=2 тул эхний гишүүн 4; тавдугаар язгуур k+1.')
    angle=[15,30,45,60,75][v-1];ans=S.simplify(S.cos(2*S.pi*angle/180))
    p.mc('Double angle',f'2cos²{angle}°−1 утгыг ол.',ans,'cos2θ=2cos²θ−1.',[ans+d for d in [-2,-1,1,2]])
    p.mc('Factoring limit',f'lim[x→{k}] (x−{k})/(x²−{k*k})-г ол.',F(1,2*k),'Хуваарь=(x−k)(x+k); хураагаад x=k орлуул.')
    p.mc('Dot product from lengths and sine',f'|a|=√{2*13*k}, |b|=√{13*k}, хоорондох өнцөг arcsin(5/13). a·b-г ол.',f'{12*k}√2','Өнцөг хурц тул cos=12/13. Уртнуудын үржвэр 13k√2.',[f'{5*k}√2',f'{13*k}√2',f'{12*k}',f'{5*k}'])
    p.mc('Power difference',f'({k+2}⁸−{k+2}⁷)/{k+1} илэрхийллийг хялбарчил.',(k+2)**7,'a⁸−a⁷=a⁷(a−1).')
    # sqrt(x+1)=x-1 has only x=3; translate both appearances.
    p.mc('Radical equation',f'√(x−{k-1})=x−{k+1} тэгшитгэлийг бод.',k+3,'u=x−k гэвэл √(u+1)=u−1; u≥1. Квадратлаад u=0,3; зөвхөн 3.')
    p.mc('Cone lateral area',f'Байгуулагч {13*k}, өндөр {12*k} конусын хажуу гадаргуугийн талбайг ол.',f'{65*k*k}π','r=√(l²−h²)=5k; S=πrl.',[f'{60*k*k}π',f'{156*k*k}π',f'{25*k*k}π',f'{169*k*k}π'])
    p.mc('Log base conversion',f'log_{k+2}8 / log_√{k+2}16 утгыг ол.',F(3,8),'ln8/lnb-ийг ln16/[(lnb)/2]-д хуваавал 3/8.')
    p.mc('Multiplication rule round trip',f'А→Б чиглэлд {k} зам, Б→В чиглэлд {k+2} зам бий. А→Б→В→Б→А аяллын боломжийн тоог ол. Зам давтан ашиглаж болно.',k*k*(k+2)**2,'Дөрвөн хэсгийн сонголтыг үржүүлнэ: k(k+2)(k+2)k.')
    # Translate original quadratic exponent, with same integer boundary width.
    p.mc('Exponential quadratic inequality',f'(1/5)^(−(x−{k})²+(x−{k})+9)>125 тэнцэтгэл бишийг бод.',f'(−∞; {k-3}) ∪ ({k+4}; +∞)','Илтгэгчийг 5 сууринд шилжүүлбэл u²−u−9>3, өөрөөр (u−4)(u+3)>0.',[f'({k-3}; {k+4})',f'(−∞; {k-3}] ∪ [{k+4}; +∞)',f'({k-4}; {k+3})','R'])
    p.mc('Arithmetic middle sum',f'Арифметик прогрессийн a₅={k+4}. S₉-ийг ол.',9*(k+4),'Тэгш хэмтэй хос бүрийн нийлбэр 2a₅; S₉=9a₅.')
    a=k+2;b=k
    p.mc('Nested radical rationalization',f'2/√({a+b}+2√{a*b})+√{b}-г хялбарчил.',f'√{a}','√(a+b+2√ab)=√a+√b. a−b=2 тул 2/(√a+√b)=√a−√b.',[f'√{b}',f'√{a}+√{b}',f'2√{a}',f'√{a}−2√{b}'])
    words=[('СУРГАЛТ',5,7),('БОЛОВСРОЛ',6,9),('САМБАР',4,6),('НОМЫН',3,5),('ДЭВТЭР',4,6)]
    word,cnt,N=words[v-1]
    p.mc('Letter sampling',f'«{word}» үгийн үсгийн байрлалаас хоёрыг буцаахгүйгээр сонгоно. Хоёулаа гийгүүлэгч байх магадлалыг ол.',F(cnt*(cnt-1),N*(N-1)),'Үсгийн ижил дүрстэй байрлалууд ч тусдаа сонголт. C(c,2)/C(n,2).')
    up=10+v;down=9+v;change=F((100+up)*(100-down)-10000,100)
    p.mc('Successive percentage changes',f'Барааны үнэ {up}% өсөөд {down}% буурав. Анхны үнэтэй харьцуулахад хэдэн хувиар өөрчлөгдөв? Эерэг бол өсөлт, сөрөг бол бууралт.',change,'Үнийн үржигдэхүүн (1+up/100)(1−down/100); нэгийг хасаад 100-аар үржүүл.')
    p.mc('Comparing real expressions',f'log_{k+2}({k+2}), {k+2}^(log_{k+2}2), ∛9, sin(3π/2), √10 тоонуудаас хамгийн бага УТГЫГ ол.',-1,'sin(3π/2)=−1; логарифм 1 ба бусад тоонууд эерэг.')
    p.mc('Logarithm substitution',f'2log_x2+log₄x=5/2. log₁₀({k}x+{32*k}/x)-ийн утгыг ол.',f'log₁₀{18*k}','t=log₂x≠0 гэвэл 2/t+t/2=5/2 → t=1,4; x=2,16. Аль алинд x+32/x=18.',[f'log₁₀{16*k}',f'log₁₀{34*k}',f'log₁₀{9*k}',f'log₁₀{32*k}'])
    p.mc('Radical rational domain',f'y=√(−{k*k}/x+1) функцийн мужийг ол.',f'(−∞; 0) ∪ [{k*k}; +∞)','(x−k²)/x≥0, x≠0; тэмдгийн хүснэгт хэрэглэ.',[f'[0; {k*k}]',f'(0; {k*k}]',f'[{k*k}; +∞)','R'])
    p.mc('Identity recognition','Аль тэнцэтгэл бүх бодит x-д үнэн биш вэ?',f'sin2x={k}sin²x','sin2x=2sinx cosx; x=0.3 гэх мэтээр худал болохыг харуулж болно.', ['cos2x=cos²x−sin²x','sin²x+cos²x=1','1+tan²x=1/cos²x (cosx≠0)','sin(π/2−x)=cosx'])
    p.mc('Factorial sequence ratio',f'aₙ={k}^(n−1)/(n−1)! бол aₙ₊₁/aₙ-г ол.',f'{k}/n','Зэрэг нэгээр нэмэгдэж, факториал n-ээр үржигдэнэ.',[f'n/{k}',f'{k}/(n−1)',f'{k}n',f'{k}/(n+1)'])
    p.mc('Area under quadratic',f'y=0 ба y={k}x²−{k} муруйгаар хүрээлсэн талбайг ол.',F(4*k,3),'Огтлолууд ±1; ∫[-1,1] k(1−x²)dx=4k/3.')
    N=80+2*v
    p.mc('Binomial alternating sum',f'Σ[j=0…{N}] C({N},j)(−1)^j{k}^j нийлбэрийг ол.',f'{k-1}^{N}','Биномын томьёогоор (1−k)^N; N тэгш тул (k−1)^N.',[f'{k}^{N}',f'{k+1}^{N}',f'{k-1}^{N-1}',f'−{k-1}^{N}'])
    p.mc('Trig inequality',f'sin(x−{k}π/6)cos(x−{k}π/6)<√2/4 тэнцэтгэл бишийг бод.',f'x∉[{k}π/6+π/8+πn; {k}π/6+3π/8+πn], n∈Z','2sin u cos u=sin2u. sin2u≥√2/2 байх хаалттай завсруудыг хасна.',[f'x∈[{k}π/6+π/8+πn; {k}π/6+3π/8+πn], n∈Z',f'x∈({k}π/6+π/8+πn; {k}π/6+3π/8+πn), n∈Z','Бүх бодит x','Шийдгүй'])
    p.mc('Cubic decreasing interval length',f'f(x)=x³/3−{F(2*k+1,2)}x²+{k*(k+1)}x. Буурах завсрын уртыг ол.',1,'f′=(x−k)(x−k−1); буурах муж (k,k+1).')
    p.mc('Exponential inverse value',f'f(x)=4^(8x−5)+{k+30}. f⁻¹({k+94})-ийг ол.',1,'f(x)=k+94 гэвэл 4^(8x−5)=64=4³; x=1.')
    p.mc('Trig roots product',f'cos²x−sin²x=sin x тэгшитгэлийн [−π+π/{k+4};π+π/{k+4}] дэх шийдүүдийн үржвэрийг ол.',f'−5π³/72','s=sinx: 1−2s²=s → s=1/2,−1; шийдүүд π/6,5π/6,−π/2.', ['5π³/72','−π³/72','−5π³/36','0'])
    b=k+2
    p.mc('Quadratic log inequality',f'(log_(1/{b})x)²−3log_(1/{b})x+2≤0-г бод.',f'[{F(1,b*b)}; {F(1,b)}]','t²−3t+2≤0 →1≤t≤2. Суурь<1 тул x=b^(−t).',[f'({F(1,b*b)}; {F(1,b)})',f'[{b}; {b*b}]',f'(0; {F(1,b*b)}]','R'])
    p.mc('Triangle heights',f'ABC хурц өнцөгт гурвалжны B-ээс AC-д буулгасан өндөр {F(16*k,5)}, A-аас BC-д буулгасан AE={4*k}. BE:EC=1:3. AC-г ол.',5*k,'BE=t, EC=3t. AB²=t²+16k², AC²=9t²+16k². Талбайгаас BC·4k=AC·(16k/5) → AC=5t. 25t²=9t²+16k²→t=k.')
    p.mc('Common tangent trapezoid area',f'{2*k}, {18*k} радиустай хоёр тойрог гадаад байдлаар шүргэлцэнэ. Ерөнхий гадна шүргэгчийн шүргэлтийн цэгүүд ба төвүүдээр үүссэн дөрвөн өнцөгтийн талбайг ол.',120*k*k,'Төвүүдийн зай 20k, радиусын зөрүү 16k; шүргэгчийн завсар 12k. Параллель талууд 2k,18k тул S=(20k)·12k/2.')
    p.mc('Regular triangular frustum volume',f'Зөв гурвалжин огтлогдсон пирамидын суурийн талууд {4*k}, {6*k}; хажуу ирмэг суурьтай 30° өнцөг үүсгэнэ. Эзлэхүүнийг ол.',f'{38*k**3}√3/9','Оройнуудын проекцын зай (6k−4k)/√3. Өндөр=2k/3. Суурийн талбайнууд 4k²√3,9k²√3. V=h(S₁+S₂+√S₁S₂)/3=38k³√3/9.',wrong=[f'{38*k**3}√3/3',f'{19*k**3}√3/9',f'{38*k**3}/9',f'{76*k**3}√3/9'])
    m=k
    p.multi('2.1','Induction divisibility proof',f'n≥1 үед F(n)=4^n+{9*m+6}n+{9*m+8} нь 9-д хуваагдахыг индукцээр батал.', [('F(1)',18*m+18),('F(n+1)−4F(n)',f'−{3*(9*m+6)}n−{18*m+18}'),('9-өөр хуваасан шилжилтийн илэрхийлэл',f'−{3*m+2}n−{2*m+2}')],'F(1)=18m+18 нь 9-д хуваагдана. F(n+1)−4F(n)=−3(9m+6)n−18m−18=−9[(3m+2)n+2m+2]. Индукцийн таамагтай нэгтгэвэл F(n+1) ч хуваагдана.')
    a=k+4
    p.multi('2.2','Product to sum trig equation',f'sin({a}x)cos({a+1}x)=sin({a-2}x)cos({a-1}x) тэгшитгэлийг бод.', [('Үржвэрийн ялгаврын хувиргасан хэлбэр',f'sin({2*a+1}x)−sin({2*a-3}x)=0'),('Үржвэрт задаргаа',f'2cos({2*a-1}x)sin(2x)=0'),('Шийдийн нэгдэл',f'x=πn/2 эсвэл x=(π/2+πn)/{2*a-1}, n∈Z')],'2sin u cos v=sin(u+v)+sin(u−v). Хоёр талын −sinx хасагдана. Нийлбэрийг үржвэрт хувирга.')
    shift=v
    outcomes=[a+b+shift for a in range(1,7) for b in range(1,7)]
    p.multi('2.3','Two dice distribution',f'Хоёр шударга шооны нүдний нийлбэр дээр {shift} нэмснийг X гэв.', [(f'X={6+shift} давтамж',5),(f'X={7+shift} давтамж',6),(f'P(X={7+shift})',F(1,6)),(f'P({3+shift}≤X≤{7+shift})',F(20,36)),(f'P(X≤{6+shift})',F(5,12))],'36 тэнцүү боломжийг хүснэгтэл. Нийлбэрүүдийн давтамж 1,2,3,4,5,6,5,4,3,2,1.')
    # Coordinates allow independent verification of skew-line metrics, same geometry as source.
    a=S.Matrix([0,0,0]);b=S.Matrix([8*k*S.sqrt(2),0,0]);c=S.Matrix([4*k*S.sqrt(2),4*k*S.sqrt(6),0]);s=c+S.Matrix([0,0,8*k]);E=(b+c)/2;D=(a+b)/2;u=E-s;w=D-c;cos=S.simplify(abs(u.dot(w))/(S.sqrt(u.dot(u))*S.sqrt(w.dot(w))));dist=S.simplify(abs((c-s).dot(u.cross(w)))/S.sqrt(u.cross(w).dot(u.cross(w))))
    p.multi('2.4','Skew lines in triangular pyramid',f'ABC зөв гурвалжны тал {8*k}√2. SC={8*k}, SC⊥(ABC). E нь BC-ийн, D нь AB-ийн дундаж цэг. SE ба CD шулуунуудын хоорондох хурц өнцөг, зайг ол.', [('Өнцгийн косинус',cos),('Хурц өнцөг','60°'),('Шулуунуудын хоорондох зай',dist)],'Координат сонго: A=(0,0,0), B=(8k√2,0,0), C=(4k√2,4k√6,0), S=C+(0,0,8k). u=E−S, w=D−C. cosθ=|u·w|/(|u||w|); d=|(C−S)·(u×w)|/|u×w|.')
    p.save()

if __name__=='__main__':
    for v in range(1,6):make(v)
